view_definitions.DDL:
CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_INGREDIENTS_ELECTRICITE" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "LIBELLEEXTACTE", "TVA", "FILEPATH", "RESTE", "TYPESTOCK", "REFPOST", "REFQUALIFICATION", "IDCHAMBRE", "ISPERISHABLE", "PV2", "IDFAMILLE", "IDMAGASIN", "PARFUMS", "ISPETRI", "TYPECONSO", "COMPTE_TVA", "TYPEPRODUIT") AS
SELECT aic."ID",aic."LIBELLE",aic."SEUIL",aic."UNITE",aic."QUANTITEPARPACK",aic."PU",aic."ACTIF",aic."PHOTO",aic."CALORIE",aic."DURRE",aic."COMPOSE",aic."CATEGORIEINGREDIENT",aic."IDFOURNISSEUR",aic."DATY",aic."QTELIMITE",aic."PV",aic."LIBELLEVENTE",aic."SEUILMIN",aic."SEUILMAX",aic."PUACHATUSD",aic."PUACHATEURO",aic."PUACHATAUTREDEVISE",aic."PUVENTEUSD",aic."PUVENTEEURO",aic."PUVENTEAUTREDEVISE",aic."ISVENTE",aic."ISACHAT",aic."COMPTE_VENTE",aic."COMPTE_ACHAT",aic."LIBELLEEXTACTE",aic."TVA",aic."FILEPATH",aic."RESTE",aic."TYPESTOCK",aic."REFPOST",aic."REFQUALIFICATION",aic."IDCHAMBRE",aic."ISPERISHABLE",aic."PV2",aic."IDFAMILLE",aic."IDMAGASIN",aic."PARFUMS",aic."ISPETRI",aic."TYPECONSO",aic."COMPTE_TVA",aic."TYPEPRODUIT"
FROM AS_INGREDIENTS_CONSOMMABLE aic WHERE aic.unite = 'UNT001105';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_INGREDIENTS_MAGASIN" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "LIBELLEEXTACTE", "TVA", "FILEPATH", "RESTE", "TYPESTOCK", "IDMAGASIN") AS
SELECT ai.ID,ai.LIBELLE,ai.SEUIL,ai.UNITE,ai.QUANTITEPARPACK,ai.PU,ai.ACTIF,ai.PHOTO,ai.CALORIE,ai.DURRE,ai.COMPOSE,ai.CATEGORIEINGREDIENT,ai.IDFOURNISSEUR,ai.DATY,ai.QTELIMITE,ai.PV,ai.LIBELLEVENTE,ai.SEUILMIN,ai.SEUILMAX,ai.PUACHATUSD,ai.PUACHATEURO,ai.PUACHATAUTREDEVISE,ai.PUVENTEUSD,ai.PUVENTEEURO,ai.PUVENTEAUTREDEVISE,ai.ISVENTE,ai.ISACHAT,ai.COMPTE_VENTE,ai.COMPTE_ACHAT,ai.LIBELLEEXTACTE,ai.TVA,ai.FILEPATH,ai.RESTE,ai.TYPESTOCK,
	m.ID  AS IDMAGASIN FROM AS_INGREDIENTS ai ,MAGASINPOINT m;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTEFABLIBST" ("ID", "IDINGREDIENTS", "UNITE", "QTEAV", "QUANTITE", "IDPRODUITS", "LIBINGREDIENTS", "TYPESTOCK", "SORTIE", "RESTE") AS
select th."ID",th."IDINGREDIENTS",th."UNITE",th."QTEAV",th."QUANTITE",th."IDPRODUITS",th."LIBINGREDIENTS",th."TYPESTOCK",cast(nvl(st.sortie,0) as number(30,2)) as sortie,cast(th.QUANTITE-nvl(st.sortie,0) as number(30,2)) as reste from as_recetteFabLib th
    left join stockEtDepenseFab st on st.IDOBJET=th.IDPRODUITS and st.IDPRODUIT=th.IDINGREDIENTS;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECFABLIBGROUPE" ("IDPRODUITS", "IDINGREDIENTS", "UNITE", "QUANTITE", "QTEAV", "PU", "LIBINGREDIENTS", "CATEGORIEINGREDIENT") AS
select a.IDPRODUITS,a.idingredients,max(a.unite) as unite,sum(quantite) as quantite, avg(a.qteav) as qteav,avg(a.pu) AS pu, a.libIngredients,a.categorieingredient
from as_recetteFabLib a group by a.IDPRODUITS, a.idingredients, a.libIngredients,a.categorieingredient;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEGORIEINGREDIENTLIB" ("ID", "VAL", "DESCE") AS
select cat.id,cat.val,ti.val as DESCE from CATEGORIEINGREDIENT cat
left join typeCATEGORIEINGREDIENT ti on cat.DESCE=ti.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."COMMANDEFILLE_ARBIOCHEM" ("ID", "PRODUIT", "IDC", "QUANTITE", "PU", "MONTANT", "TVA", "REMISE", "IDDEVISE", "UNITE", "DESIGNATION", "RISTOURNE", "CALORIE", "MONTANTRISTOURNE", "MONTANTREMISE") AS
select "ID","PRODUIT","IDC","QUANTITE","PU","MONTANT","TVA","REMISE","IDDEVISE","UNITE","DESIGNATION","RISTOURNE","CALORIE",    0 AS montantRistourne,
       0 AS montantRemise from COMMANDEFILLE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."DEMTRANSFILLEGROUPEMERE" ("IDDEMANDETRANSFERT", "MONTANTQUANTITE") AS
select f.IDDEMANDETRANSFERT,cast(sum(nvl(f.pu*f.QUANTITE,0)) as number(30,2)) as montantQuantite
from DEMANDETRANSFERTFILLE f group by f.IDDEMANDETRANSFERT;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FABRICATIONFILLEPU" ("ID", "IDINGREDIENTS", "LIBELLE", "REMARQUE", "IDMERE", "DATYBESOIN", "QTE", "IDUNITE", "PU", "IDBCFILLE", "OPERATEUR") AS
select f.id, f.idingredients, f.libelle, f.remarque, f.idmere, f.datybesoin, f.qte, f.idunite, a.pu, f.IDBCFILLE,f.OPERATEUR
from FABRICATIONFILLE f left join AS_INGREDIENTS a on f.IDINGREDIENTS=a.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FABRICATIONRATTACHE" ("IDFAB", "IDINGREDIENTS", "LIBELLE", "REMARQUE", "IDMERE", "DATYBESOIN", "QTE", "IDUNITE", "PU", "IDBCFILLE", "OPERATEUR", "NIVEAU", "IDMACHINE", "IDLIGNE", "LIGNE", "DATY", "ID", "IDRELEVE", "POURCENTAGE") AS
SELECT f.ID AS idFab ,f.IDINGREDIENTS,f.LIBELLE,f.REMARQUE,f.IDMERE,f.DATYBESOIN,f.QTE,f.IDUNITE,f.PU,f.IDBCFILLE,f.OPERATEUR,f.NIVEAU,f.IDMACHINE,f.IDLIGNE,f.LIGNE,f.DATY, r.id  ,r.idreleve AS idreleve, CAST((f.QTE  / SUM(f.QTE ) OVER (PARTITION BY r.IDRELEVE)) * 100 AS NUMBER(30,2) ) AS POURCENTAGE FROM FABRICATIONFILLEPETRI f
	JOIN RELEVEFAB r ON r.IDFAB = f.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."FACTUREFOURNISSEUR_PAYELIVRE" ("ID", "IDFOURNISSEUR", "IDFOURNISSEURLIB", "IDMODEPAIEMENT", "IDMODEPAIEMENTLIB", "DATY", "DESIGNATION", "DATEECHEANCEPAIEMENT", "ETAT", "ETATLIB", "REFERENCE", "IDBC", "IDMAGASIN", "DEVISE", "TAUX", "IDMAGASINLIB", "MONTANT", "MONTANTPAYER", "MONTANTRESTE") AS
SELECT "ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","MONTANT","MONTANTPAYER","MONTANTRESTE"FROM FACTUREFOURNISSEURCPL_montant
WHERE ETAT = 14;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREFILLEGROUPEMERE" ("IDINVENTAIRE", "MONTANTQUANTITE") AS
select f.IDINVENTAIRE,cast(sum(nvl(f.pu*f.QUANTITE,0)) as number(30,2)) as montantQuantite
from INVENTAIREFILLE f group by f.IDINVENTAIRE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."INVENTAIREFILLEVIDE" ("ID", "IDINVENTAIRE", "IDPRODUIT", "EXPLICATION", "IDJAUGE", "QUANTITETHEORIQUE", "QUANTITE", "MVTSOURCE", "PU", "IDFOURNISSEUR", "DATY") AS
select 'invvidef'||mfv.ID as id,'invVide' as idinventaire,mfv.IDPRODUIT,'inv Auto Vide' as explication,null as idjauge,cast( 0 as number(30,10)) as QUANTITETHEORIQUE,cast(0 as number(30,10)) as quantite,mfv.ID as mvtsource
         ,cast(1 as number(30,5)) as pu,null as idfournisseur, null as daty from mvtStockFilleSansInventaire mfv;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LIAISONPAIEMENTMVTCAISSEGRP" ("IDMVTCAISSE", "MONTANT") AS
select id1 as idmvtcaisse, sum(MONTANT) as montant from LIAISONPAIEMENT where etat = 11
group by id1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."LIAISONPAIEMENTMVTCAISSEGRP2" ("IDMVTCAISSE", "MONTANT") AS
select id1 as idmvtcaisse, cast(sum(nvl(MONTANT, 0)) as number(30,2)) as montant from LIAISONPAIEMENT where etat = 11
group by id1;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSECPL_NATTACH" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "ETATLIB", "IDVENTE", "IDORIGINE", "IDTIERS", "TIERS", "IDPREVISION", "IDOP", "TAUX", "COMPTE", "IDDEVISE") AS
SELECT "ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","ETATLIB","IDVENTE","IDORIGINE","IDTIERS","TIERS","IDPREVISION","IDOP","TAUX","COMPTE","IDDEVISE" FROM MOUVEMENTCAISSECPL m  
WHERE NOT EXISTS (SELECT mvp.id FROM MVTCAISSEPREVISION mvp WHERE mvp.id1=m.id) AND m.ETAT >=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSEFILLECPL" ("ID", "DESIGNATION", "IDCAISSE", "IDVENTEDETAIL", "IDVIREMENT", "DATY", "ETAT", "IDOP", "IDORIGINE", "IDDEVISE", "IDTIERS", "COMPTE", "IDPREVISION", "IDTRAITE", "ETATVERSEMENT", "IDMODEPAIEMENT", "IDMVTCAISSEMERE", "REFERENCE", "UPDATED_AT", "DATYCOMPTABILISATION", "ACQUEREUR", "IDTYPEPAIEMENT", "DEBIT", "CREDIT", "TAUX", "HEURE", "IDREPORT", "IDCAISSIER", "MONTANTRETOURNER", "IDCAISSELIB") AS
select m."ID",m."DESIGNATION",m."IDCAISSE",m."IDVENTEDETAIL",m."IDVIREMENT",m."DATY",m."ETAT",m."IDOP",m."IDORIGINE",m."IDDEVISE",m."IDTIERS",m."COMPTE",m."IDPREVISION",m."IDTRAITE",m."ETATVERSEMENT",m."IDMODEPAIEMENT",m."IDMVTCAISSEMERE",m."REFERENCE",m."UPDATED_AT",m."DATYCOMPTABILISATION",m."ACQUEREUR",m."IDTYPEPAIEMENT",m."DEBIT",m."CREDIT",m."TAUX",m."HEURE",m."IDREPORT",m."IDCAISSIER",m."MONTANTRETOURNER", c.VAL as idCaisseLib from mouvementcaisse m
left join caisse c on m.IDCAISSE = c.id;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MOUVEMENTCAISSE_VISE" ("ID", "DESIGNATION", "IDCAISSE", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDORIGINE", "IDDEVISE", "TAUX", "IDTIERS", "COMPTE", "IDPREVISION", "IDTRAITE", "ETATVERSEMENT", "IDMODEPAIEMENT", "IDMVTCAISSEMERE", "REFERENCE") AS
select "ID","DESIGNATION","IDCAISSE","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDORIGINE","IDDEVISE","TAUX","IDTIERS","COMPTE","IDPREVISION","IDTRAITE","ETATVERSEMENT","IDMODEPAIEMENT","IDMVTCAISSEMERE","REFERENCE" from MOUVEMENTCAISSE
WHERE ETAT=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTCAISSEGROUPPREVISIONSOM" ("ID", "ID1", "ID2", "ETAT", "REMARQUE", "MONTANTMERE", "MONTANTCREDIT", "TAUX", "DEVISE") AS
SELECT '-' AS id, id1,'' AS id2,etat,'-' AS remarque,sum(montantMere) AS montantMere,sum(montantCredit) AS montantCredit,nvl(max(taux),1) AS taux,devise 
FROM MVTCAISSEPREVISIONVise GROUP BY id1,etat,devise;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTCAISSESOMPREVISIONGROUP" ("ID", "ID1", "ID2", "ETAT", "REMARQUE", "MONTANTMERE", "MONTANTCREDIT", "TAUX", "DEVISE") AS
SELECT '-' AS id, '' AS id1,id2,etat,'-' AS remarque,sum(montantMere) AS montantMere,sum(montantCredit) AS montantCredit,nvl(max(taux),1) AS taux,devise  
FROM MVTCAISSEPREVISIONVise GROUP BY id2,etat,devise;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTOCKFILLEFABVISE" ("ID", "IDMVTSTOCK", "IDPRODUIT", "ENTREE", "SORTIE", "IDVENTEDETAIL", "IDTRANSFERTDETAIL", "PU", "MVTSRC", "RESTE", "DESIGNATION", "IDFAB") AS
select st."ID",st."IDMVTSTOCK",st."IDPRODUIT",st."ENTREE",st."SORTIE",st."IDVENTEDETAIL",st."IDTRANSFERTDETAIL",st."PU",st."MVTSRC",st."RESTE",st."DESIGNATION",m.IDOBJET as idFab
from MVTSTOCKFILLE st left join MVTSTOCK m on st.IDMVTSTOCK=m.ID  where m.etat>=11;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERTEGAINIMPREVUELIB_NP" ("ID", "DESIGNATION", "IDTYPEGAINPERTE", "PERTE", "GAIN", "IDORIGINE", "DATY", "ETAT", "TVA", "TIERS", "TYPE", "COMPTE", "MONTANTTVA", "MONTANTHT", "MONTANTTTC", "TIERSLIB", "TIERSCOMPTE") AS
SELECT "ID","DESIGNATION","IDTYPEGAINPERTE","PERTE","GAIN","IDORIGINE","DATY","ETAT","TVA","TIERS","TYPE","COMPTE","MONTANTTVA","MONTANTHT","MONTANTTTC","TIERSLIB","TIERSCOMPTE" FROM pertegainimprevuelib_V p
where NOT EXISTS (SELECT idorigine FROM MOUVEMENTCAISSE m WHERE m.idorigine=p.id );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERTEGAINIMPREVUELIB_P" ("ID", "DESIGNATION", "IDTYPEGAINPERTE", "PERTE", "GAIN", "IDORIGINE", "DATY", "ETAT", "TVA", "TIERS", "TYPE", "COMPTE", "MONTANTTVA", "MONTANTHT", "MONTANTTTC", "TIERSLIB", "TIERSCOMPTE") AS
SELECT "ID","DESIGNATION","IDTYPEGAINPERTE","PERTE","GAIN","IDORIGINE","DATY","ETAT","TVA","TIERS","TYPE","COMPTE","MONTANTTVA","MONTANTHT","MONTANTTTC","TIERSLIB","TIERSCOMPTE" FROM pertegainimprevuelib_V p
where  EXISTS (SELECT idorigine FROM MOUVEMENTCAISSE m WHERE m.idorigine=p.id );

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISION_COMPLET_CPL_DEP" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVENTE", "IDVENTELIB", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDOPLIB", "IDORIGINE", "IDDEVISE", "IDDEVISELIB", "TAUX", "IDTIERS", "COMPTE", "EFFECTIFDEBIT", "EFFECTIFCREDIT", "DEPENSEECART", "RECETTEECART", "IDFACTURE") AS
SELECT "ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE" FROM PREVISION_COMPLET_CPL pcc  WHERE 
debit > 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISION_COMPLET_CPL_REC" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVENTE", "IDVENTELIB", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDOPLIB", "IDORIGINE", "IDDEVISE", "IDDEVISELIB", "TAUX", "IDTIERS", "COMPTE", "EFFECTIFDEBIT", "EFFECTIFCREDIT", "DEPENSEECART", "RECETTEECART", "IDFACTURE") AS
SELECT "ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE" FROM PREVISION_COMPLET_CPL pcc  WHERE 
credit > 0;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REQUETE_A_ENVOYER_SERVEUR" ("ID", "ACTION", "TABLECONCERNE", "REQUETE", "DATY", "HEURE", "SERVEUR") AS
SELECT rae.ID, rae.ACTION, rae.TABLECONCERNE, rae.REQUETE, rae.DATY, rae.HEURE, rae.SERVEUR
FROM REQUETE_A_ENVOYER rae;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESULTATPREVGROUPMOIS" ("DATY", "DEBIT", "CREDIT", "annee", "mois") AS
SELECT min(r.daty) AS daty,sum(r.debit) AS debit,sum(r.CREDIT) AS credit,r."annee", r."mois" 
FROM RESULTATPREVISIONNELTOUS r GROUP BY r."annee", r."mois";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RESULTATPREVGROUPSEMAINE" ("DATY", "DEBIT", "CREDIT", "semaine", "annee", "mois") AS
SELECT min(r.daty) AS daty,sum(r.debit) AS debit,sum(r.CREDIT) AS credit,r."semaine",r."annee", r."mois" 
FROM RESULTATPREVISIONNELTOUS r GROUP BY r."semaine",r."annee", r."mois";

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SALAIREBASEMOIS" ("IDPERSONNEL", "MOIS", "ANNEE", "SALAIREBASE") AS
SELECT IDPERSONNEL,mois,annee,round(sum(gain),0) AS salairebase FROM paie_edition WHERE IDELEMENTPAIE IN (
    SELECT id FROM PAIE_RUBRIQUE pr WHERE TYPERUBRIQUE='G' AND IMPOSABLE = 'I'
) GROUP BY IDPERSONNEL,mois,annee;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SORTIEPRODUITPARVENTE" ("IDPRODUIT", "IDOBJET", "QTESORTIE", "IDVENTE") AS
select spo."IDPRODUIT",spo."IDOBJET",spo."QTESORTIE", abc.IDVENTE from SORTIEPRODUITparorigine spo
    left join AS_BONDELIVRAISON_CLIENT abc on abc.id = spo.idobjet;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SORTIEPRODUITPARVENTEGRP" ("IDPRODUIT", "IDVENTE", "QTESORTIE") AS
select idproduit, IDVENTE, sum(qteSortie) as qteSortie from SORTIEPRODUITparvente
group by IDVENTE, idproduit;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ST_INGREDIENTSAUTOCHAMBRE" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "COMPTE") AS
SELECT ai."ID",ai."LIBELLE",ai."SEUIL",ai."UNITE",ai."QUANTITEPARPACK",ai."PU",ai."ACTIF",ai."PHOTO",ai."CALORIE",ai."DURRE",ai."COMPOSE",ai."CATEGORIEINGREDIENT",ai."IDFOURNISSEUR",ai."DATY",ai."QTELIMITE",ai."PV",ai."LIBELLEVENTE",ai."SEUILMIN", ai.COMPTE_VENTE AS compte
FROM AS_INGREDIENTS ai where ai.pv>0 and ai.CATEGORIEINGREDIENT = 'CAT001';

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TARIF_INGREDIENTS_MAX_DATE_MN" ("IDINGREDIENT", "UNITE", "IDTYPECLIENT", "DATY", "IDMAGASIN") AS
select IDINGREDIENT, UNITE, IDTYPECLIENT, max(DATY) as daty, IDMAGASIN
from (select * from TARIF_INGREDIENTS where idmagasin is null)
group by IDINGREDIENT, UNITE, IDTYPECLIENT, IDMAGASIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TARIF_INGREDIENTS_MAX_DATE_MNN" ("IDINGREDIENT", "UNITE", "IDTYPECLIENT", "DATY", "IDMAGASIN") AS
select IDINGREDIENT, UNITE, IDTYPECLIENT, max(DATY) as daty, IDMAGASIN
from (select * from TARIF_INGREDIENTS where idmagasin is not null)
group by IDINGREDIENT, UNITE, IDTYPECLIENT, IDMAGASIN;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRAITELIB_GRP" ("IDTRAITE", "CODE") AS
SELECT  IDTRAITE,LISTAGG(CODE , ';') WITHIN GROUP (ORDER BY CODE) AS CODE FROM TRAITE_FCLIB tf
GROUP BY IDTRAITE;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TRANSTOCKDETAILSGROUPEMERE" ("IDTRANSFERTSTOCK", "MONTANTQUANTITE") AS
select f.IDTRANSFERTSTOCK,cast(sum(nvl(f.pu*f.QUANTITE,0)) as number(30,2)) as montantQuantite
from TRANSFERTSTOCKDETAILS f group by f.IDTRANSFERTSTOCK;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."VENTECPLJOUR" ("DATY", "MONTANT") AS
select v.daty,sum(v.MONTANTTTC) as montant from VENTE_CPL v
group by v.daty;

CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."V_LIAISONPAIEMENT_VENTE" ("ID", "ID1", "ID2", "MONTANT", "ETAT", "IDVENTE", "DESIGNATION", "DATY") AS
select li."ID",li."ID1",li."ID2",li."MONTANT",li."ETAT",ve.id as idVente, ve.DESIGNATION,ve.daty
from LIAISONPAIEMENT li left join (select id,DESIGNATION,daty from vente union all select id,designation,daty from FACTUREFOURNISSEUR) ve on ve.id=li.ID2;

table_definitions.DDL:
  CREATE TABLE "ARBIOCHEMSTANDARD"."AGENCE" 
   (	"ID" VARCHAR2(20) NOT NULL ENABLE, 
	"VAL" VARCHAR2(30) DEFAULT '-', 
	"DESCE" VARCHAR2(100) DEFAULT '-'
   ) ;

  CREATE TABLE "ARBIOCHEMSTANDARD"."AI_MSG_REPORT" 
   (	"ID" VARCHAR2(255), 
	"EMAILADRESS" VARCHAR2(255), 
	"EMAIL_MSG_TYPE" VARCHAR2(255), 
	 PRIMARY KEY ("ID") ENABLE
   ) ;

  CREATE TABLE "ARBIOCHEMSTANDARD"."AI_MSG_REPORT_TYPE" 
   (	"ID" VARCHAR2(255), 
	"VAL" VARCHAR2(255), 
	"DESCE" VARCHAR2(255), 
	 PRIMARY KEY ("ID") ENABLE
   ) ;

CREATE TABLE "ARBIOCHEMSTANDARD"."ALL_VUE" 
 (	"VIEW_NAME" VARCHAR2(30) NOT NULL ENABLE
 ) ;

  CREATE TABLE "ARBIOCHEMSTANDARD"."ANNULATIONUTILISATEUR" 
   (	"IDANNULATIONUSER" VARCHAR2(20), 
	"REFUSER" NUMBER(20,0), 
	"DATY" DATE, 
	 PRIMARY KEY ("IDANNULATIONUSER") ENABLE
   ) ;

  CREATE TABLE "ARBIOCHEMSTANDARD"."ARTICLEPRIX" 
   (	"IDPRODUIT" VARCHAR2(2000), 
	"IPRODUIT" VARCHAR2(255), 
	"PUMP" NUMBER
   ) ;

  CREATE TABLE "ARBIOCHEMSTANDARD"."BANQUE" 
   (	"ID" VARCHAR2(100) NOT NULL ENABLE, 
	"VAL" VARCHAR2(500), 
	"DESCE" VARCHAR2(500), 
	 CONSTRAINT "PK_BANQUE" PRIMARY KEY ("ID") ENABLE
   ) ;

  CREATE TABLE "ARBIOCHEMSTANDARD"."CALENDRIER" 
   (	"ID" VARCHAR2(255), 
	"DATY" DATE, 
	"EVENEMENT" VARCHAR2(255), 
