 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_BONDECOMMANDE_CPL_RECEPTGRP" ("IDBC", "TOTALCOMMANDE", "TOTALRECEPT") AS 
 SELECT bc.idbc, sum (bc.quantite ) AS totalCommande , sum (bc.qtelivrer ) AS totalRecept FROM AS_BONDECOMMANDE_CPL_RECEPT bc GROUP BY bc.idbc 

;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_BONDELIVRAISONC_LIBCPL_A" ("ID", "REMARQUE", "IDVENTE", "IDBC", "DATY", "ETAT", "MAGASIN", "IDORIGINE", "IDCLIENT", "IDMAGASINLIB", "IDCLIENTLIB", "ETATLIB") AS 
 SELECT "ID","REMARQUE","IDVENTE","IDBC","DATY","ETAT","MAGASIN","IDORIGINE","IDCLIENT","IDMAGASINLIB","IDCLIENTLIB","ETATLIB" FROM AS_BONDELIVRAISONCLIENT_LIBCPL WHERE etat=0
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_INGREDIENTS_CONSOMMABLE" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "LIBELLEEXTACTE", "TVA", "FILEPATH", "RESTE", "TYPESTOCK", "REFPOST", "REFQUALIFICATION", "IDCHAMBRE", "ISPERISHABLE", "PV2", "IDFAMILLE", "IDMAGASIN", "PARFUMS", "ISPETRI", "TYPECONSO", "COMPTE_TVA", "TYPEPRODUIT") AS 
 SELECT "ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT","LIBELLEEXTACTE","TVA","FILEPATH","RESTE","TYPESTOCK","REFPOST","REFQUALIFICATION","IDCHAMBRE","ISPERISHABLE","PV2","IDFAMILLE","IDMAGASIN","PARFUMS","ISPETRI","TYPECONSO","COMPTE_TVA","TYPEPRODUIT" FROM AS_INGREDIENTS ai WHERE ai.CATEGORIEINGREDIENT = 'CAT0011' 
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_INGREDIENTS_NON_VENTE" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV") AS 
 select "ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV" from AS_INGREDIENTS where pv=0
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_INGREDIENT_PIECE" ("ID", "IDINGREDIENT", "IDENTITE", "REFERENCEOBJET", "MARQUEOBJET", "MODELEOBJET", "NUMEROSERIEOBJET", "DESCRIPTIONOBJET", "QUALITEOBJET", "ETATOBJET", "LOCALISATIONOBJET", "PUISSANCEOBJET", "OBSERVATIONOBJET", "TYPERATTACHEMENT", "ESTENGIN", "LIBELLE", "DATEAQUISITION", "INGREDIENTLIB", "IDENTITELIB", "QUALITEOBJETLIB", "ETATOBJETLIB", "LOCALISATIONOBJETLIB", "ESTENGINLIB", "IDLIGNE", "IDLIGNELIB", "PU") AS 
 SELECT "ID","IDINGREDIENT","IDENTITE","REFERENCEOBJET","MARQUEOBJET","MODELEOBJET","NUMEROSERIEOBJET","DESCRIPTIONOBJET","QUALITEOBJET","ETATOBJET","LOCALISATIONOBJET","PUISSANCEOBJET","OBSERVATIONOBJET","TYPERATTACHEMENT","ESTENGIN","LIBELLE","DATEAQUISITION","INGREDIENTLIB","IDENTITELIB","QUALITEOBJETLIB","ETATOBJETLIB","LOCALISATIONOBJETLIB","ESTENGINLIB","IDLIGNE","IDLIGNELIB","PU" FROM As_ingredient_maintenance_lib WHERE IDENTITE = 'ENT000004'
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_MACHINE" ("ID", "LIBELLE", "PARFUMS", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "COMPOSELIB", "IDCATEGORIEINGREDIENT", "CATEGORIEINGREDIENT", "IDCATEGORIE", "IDFOURNISSEUR", "DATY", "BIENOUSERV", "ETATLIB", "COMPTE_VENTE", "COMPTE_ACHAT", "PV", "TVA", "TYPESTOCK", "IDUNITE", "REFPOST", "REFQUALIFICATION", "REFPOSTLIB", "REFQUALIFICATIONLIB", "IDFAMILLELIB") AS 
 SELECT "ID","LIBELLE","PARFUMS","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","COMPOSELIB","IDCATEGORIEINGREDIENT","CATEGORIEINGREDIENT","IDCATEGORIE","IDFOURNISSEUR","DATY","BIENOUSERV","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT","PV","TVA","TYPESTOCK","IDUNITE","REFPOST","REFQUALIFICATION","REFPOSTLIB","REFQUALIFICATIONLIB","IDFAMILLELIB" FROM AS_INGREDIENTS_LIB ai WHERE ai.IDCATEGORIEINGREDIENT = 'CAT005'
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_PRODUITS" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT") AS 
 select "ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT" from AS_INGREDIENTS where pv>0
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AS_RECETTEFABLIBSERVICE" ("ID", "IDINGREDIENTS", "UNITE", "QTEAV", "QUANTITE", "IDPRODUITS", "LIBINGREDIENTS", "TYPESTOCK", "CATEGORIEINGREDIENT") AS 
 SELECT ID,IDINGREDIENTS,UNITE,QTEAV,QUANTITE,IDPRODUITS,LIBINGREDIENTS,TYPESTOCK,categorieingredient FROM As_recetteFabLib WHERE TYPESTOCK IS NULL AND UNITE = 'UNT003' AND CATEGORIEINGREDIENT!='CAT002'
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVANCE_LIB_CREE" ("ID", "IDPERSONNEL", "MONTANT", "NBREMBOURSEMENT", "REMARQUE", "DATY", "DATEAVANCE", "INTERET", "ETAT", "ETATLIB", "IDTYPEAVANCE", "IDTYPEAVANCELIB", "MATRICULE") AS 
 select "ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","ETATLIB","IDTYPEAVANCE","IDTYPEAVANCELIB","MATRICULE" from AVANCE_LIB2 where etat = 1 
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVANCE_LIB_PAYE" ("ID", "IDPERSONNEL", "MONTANT", "NBREMBOURSEMENT", "REMARQUE", "DATY", "DATEAVANCE", "INTERET", "ETAT", "ETATLIB", "IDTYPEAVANCE", "IDTYPEAVANCELIB", "MATRICULE") AS 
 select "ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","ETATLIB","IDTYPEAVANCE","IDTYPEAVANCELIB","MATRICULE" from AVANCE_LIB2 where etat = 21 
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVANCE_LIB_VISEE" ("ID", "IDPERSONNEL", "MONTANT", "NBREMBOURSEMENT", "REMARQUE", "DATY", "DATEAVANCE", "INTERET", "ETAT", "ETATLIB", "IDTYPEAVANCE", "IDTYPEAVANCELIB", "MATRICULE") AS 
 select "ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","ETATLIB","IDTYPEAVANCE","IDTYPEAVANCELIB","MATRICULE" from AVANCE_LIB2 where etat = 11 
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFC_GRP_ANNULEE" ("IDAVOIRFC", "COMPTE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "ETAT", "TAUXDECHANGE") AS 
 select "IDAVOIRFC","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","ETAT","TAUXDECHANGE" from AVOIRFC_GRP_TOUS where etat < 1
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFC_GRP_CREEE" ("IDAVOIRFC", "COMPTE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "ETAT", "TAUXDECHANGE") AS 
 select "IDAVOIRFC","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","ETAT","TAUXDECHANGE" from AVOIRFC_GRP_TOUS where etat = 1
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."AVOIRFC_GRP_VISEE" ("IDAVOIRFC", "COMPTE", "MONTANTHT", "MONTANTTVA", "MONTANTTTC", "MONTANTHTAR", "MONTANTTVAAR", "MONTANTTTCAR", "ETAT", "TAUXDECHANGE") AS 
 select "IDAVOIRFC","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","ETAT","TAUXDECHANGE" from AVOIRFC_GRP_TOUS where etat >= 11
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDEFACTURER" ("PRODUIT", "QUANTITE", "IDPROFORMA") AS 
 select PRODUIT,sum(bcf.QUANTITE) - sum(vdf.QTE) as quantite, bc.IDPROFORMA from bondecommande_client_fille bcf join VENTE_DETAILS vdf ON bcf.id = vdf.idbcfille join vente v on v.id=vdf.IDVENTE join BONDECOMMANDE_CLIENT bc on bc.ID=bcf.IDBC where v.ETAT>=11 group by PRODUIT, bc.IDPROFORMA
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDE_CLIENT_CPL_A" ("ID", "DATY", "ETAT", "REMARQUE", "DESIGNATION", "MODEPAIEMENT", "MODEPAIEMENTLIB", "IDCLIENT", "IDCLIENTLIB", "REFERENCE", "ETATLIB") AS 
 SELECT "ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","ETATLIB" FROM BONDECOMMANDE_CLIENT_CPL WHERE etat=0
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDE_CLIENT_CPL_C" ("ID", "DATY", "ETAT", "REMARQUE", "DESIGNATION", "MODEPAIEMENT", "MODEPAIEMENTLIB", "IDCLIENT", "IDCLIENTLIB", "REFERENCE", "ETATLIB") AS 
 SELECT "ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","ETATLIB" FROM BONDECOMMANDE_CLIENT_CPL WHERE etat=1
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BONDECOMMANDE_CLIENT_CPL_V" ("ID", "DATY", "ETAT", "REMARQUE", "DESIGNATION", "MODEPAIEMENT", "MODEPAIEMENTLIB", "IDCLIENT", "IDCLIENTLIB", "REFERENCE", "ETATLIB") AS 
 SELECT "ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","ETATLIB" FROM BONDECOMMANDE_CLIENT_CPL WHERE etat=11
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."BUDGET_DEPENSE_SUM_VIEW_BUDGET" ("COMPTE", "MOIS", "ANNEE", "MOISLIB", "DEPENSES", "IDSERVICELIB", "SERVICE") AS 
 SELECT "COMPTE","MOIS","ANNEE","MOISLIB","DEPENSES","IDSERVICELIB","SERVICE" FROM budget_depense_sum_view WHERE mois IS NOT NULL AND ANNEE IS NOT NULL 
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CAISSETRAITE" ("ID", "VAL", "DESCE") AS 
 select ID,VAL,DESCE from caisse where id = 'CAIS00000T00016'
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CATEGORIE_PAIE_SALAIRE" ("ID", "VAL", "DESCE", "MONTANT", "REMARQUE", "DROIT_HEURE_SUP", "ESSAIE") AS 
 SELECT ID,VAL,DESCE,MONTANT,REMARQUE,DROIT_HEURE_SUP,ESSAIE FROM CATEGORIE_PAIE cp WHERE id in('CP0000010','CP0000011')

;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CA_JOURNALIER_UNION_GP" ("MONTANT", "ANNEE", "MOIS", "DATY") AS 
 select sum(montant) as montant, annee, mois, daty from ca_journalier_union group by annee, mois, daty

;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHARGEMONTANT" ("ID", "DATY", "LIBELLE", "PU", "TYPE", "IDFABRICATION", "ETAT", "IDINGREDIENTS", "QTE", "MONTANT") AS 
 SELECT c."ID",c."DATY",c."LIBELLE",c."PU",c."TYPE",c."IDFABRICATION",c."ETAT",c."IDINGREDIENTS",c."QTE", cast(c.pu * c.qte AS NUMBER(30,10)) AS montant FROM charge c
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHECKINAVECCHEKOUT" ("ID", "RESERVATION", "DATY", "HEURE", "REMARQUE", "CLIENT", "IDPRODUIT", "ETAT", "IDCLIENT", "QTE", "CHECKOUT") AS 
 select c."ID",c."RESERVATION",c."DATY",c."HEURE",c."REMARQUE",c."CLIENT",c."IDPRODUIT",c."ETAT",c."IDCLIENT", c.qte,o.id as checkOut from CHECKIN c left join CHECKOUT o on c.id=o.RESERVATION
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHECKINAVECCHEKOUTCOMPLET" ("RESERVATION", "ID", "DATY", "ETAT", "HEURE", "REMARQUE", "CHECKOUT") AS 
 select c.RESERVATION ,o.id,o.DATY,o.ETAT,  o.HEURE,o.REMARQUE, o.RESERVATION as checkOut from CHECKIN c left join CHECKOUT o on c.id=o.RESERVATION
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CHECKINSANSCHEKOUT" ("ID", "RESERVATION", "DATY", "HEURE", "REMARQUE", "CLIENT", "IDPRODUIT", "ETAT", "IDCLIENT") AS 
 select c."ID",c."RESERVATION",c."DATY",c."HEURE",c."REMARQUE",c."CLIENT",c."IDPRODUIT",c."ETAT",c."IDCLIENT" from CHECKIN c where c.id not in (select o.reservation from CHECKOUT o where o.ETAT>=11)
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."CLIENT_ACTIF" ("ID", "NOM", "TELEPHONE", "MAIL", "ADRESSE", "REMARQUE", "COMPTE", "IDNATIONALITE", "COMPTEAUXILIAIRE", "IDTYPECLIENT", "IDPROVINCE", "ECHEANCE", "TELFIXE", "NIF", "STAT", "CARTE", "DATECARTE", "TAXE", "CODECLIENT") AS 
