 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."MVTSTFILLEOFFCATVISEGROUPEDEP" ("IDOFF", "ENTREE", "SORTIE", "MONTANT", "MONTANTSORTIE", "PV") AS 
