 select o."ID",o."IDINGREDIENTS",o."LIBELLE",o."REMARQUE",o."IDMERE",o."DATYBESOIN",o."QTE",o."IDUNITE",o."IDBCFILLE",cast(nvl(e.QTE,1) as number(20,2)) as equivalence from OFFILLE o left join EQUIVALENCE e on o.IDINGREDIENTS=e.IDPRODUIT and o.IDUNITE=e.IDUNITE
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."OFFILLERESTELIB" ("ID", "IDINGREDIENTS", "LIBELLE", "REMARQUE", "IDMERE", "DATYBESOIN", "QTE", "IDUNITE", "QTEFABRIQUE", "QTERESTE") AS 
 SELECT o."ID",o."IDINGREDIENTS",o."LIBELLE",o."REMARQUE",o."IDMERE",o."DATYBESOIN",o."QTE",o."IDUNITE",fmf.qte AS qteFabrique,(o.qte-fmf.qte) AS qteReste FROM FabricationMereFille fmf JOIN OfFilleLib o ON fmf.idof=o.IDMERE  AND fmf.IDINGREDIENTS=o.IDINGREDIENTS
;

