 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERTEGAINIMPREVUELIB_C" ("ID", "DESIGNATION", "IDTYPEGAINPERTE", "PERTE", "GAIN", "IDORIGINE", "DATY", "ETAT", "TVA", "TIERS", "TYPE", "COMPTE", "MONTANTTVA", "MONTANTHT", "MONTANTTTC", "TIERSLIB", "TIERSCOMPTE") AS 
 SELECT "ID","DESIGNATION","IDTYPEGAINPERTE","PERTE","GAIN","IDORIGINE","DATY","ETAT","TVA","TIERS","TYPE","COMPTE","MONTANTTVA","MONTANTHT","MONTANTTTC","TIERSLIB","TIERSCOMPTE" FROM pertegainimprevuelib WHERE etat=1
