 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PERTEGAINIMPREVUELIB_V" ("ID", "DESIGNATION", "IDTYPEGAINPERTE", "PERTE", "GAIN", "IDORIGINE", "DATY", "ETAT", "TVA", "TIERS", "TYPE", "COMPTE", "MONTANTTVA", "MONTANTHT", "MONTANTTTC", "TIERSLIB", "TIERSCOMPTE") AS 
 SELECT "ID","DESIGNATION","IDTYPEGAINPERTE","PERTE","GAIN","IDORIGINE","DATY","ETAT","TVA","TIERS","TYPE","COMPTE","MONTANTTVA","MONTANTHT","MONTANTTTC","TIERSLIB","TIERSCOMPTE" FROM pertegainimprevuelib WHERE etat=11
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISIONVALIDE" ("ID", "DESIGNATION", "IDCAISSE", "IDVENTEDETAIL", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDORIGINE", "IDDEVISE", "TAUX", "IDTIERS", "COMPTE", "IDFACTURE") AS 
