;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PREVISION_TIERS" ("ID", "DESIGNATION", "IDCAISSE", "IDCAISSELIB", "IDVENTEDETAIL", "IDVENTE", "IDVENTELIB", "IDVIREMENT", "DEBIT", "CREDIT", "DATY", "ETAT", "IDOP", "IDOPLIB", "IDORIGINE", "IDDEVISE", "IDDEVISELIB", "TAUX", "IDTIERS", "COMPTE", "EFFECTIFDEBIT", "EFFECTIFCREDIT", "DEPENSEECART", "RECETTEECART", "IDFACTURE", "TIERSLIB") AS 
 select p."ID",p."DESIGNATION",p."IDCAISSE",p."IDCAISSELIB",p."IDVENTEDETAIL",p."IDVENTE",p."IDVENTELIB",p."IDVIREMENT",p."DEBIT",p."CREDIT",p."DATY",p."ETAT",p."IDOP",p."IDOPLIB",p."IDORIGINE",p."IDDEVISE",p."IDDEVISELIB",p."TAUX",p."IDTIERS",p."COMPTE",p."EFFECTIFDEBIT",p."EFFECTIFCREDIT",p."DEPENSEECART",p."RECETTEECART",p."IDFACTURE", t.nom as tierslib from PREVISION_COMPLET_CPLPositif p LEFT JOIN TIERS t on t.id = p.IDTIERS
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PRIXTEMP" ("PUTEMP", "IDPRODUIT") AS 
 SELECT AVG(PU)AS putemp,IDPRODUIT FROM V_ETATSTOCK_ENTREE vee GROUP BY IDPRODUIT 
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."PROFORMACOMMADER" ("PRODUIT", "QUANTITE", "IDPROFORMA") AS 
 select PRODUIT, sum(QUANTITE) as quantite, bc.IDPROFORMA from BONDECOMMANDE_CLIENT_FILLE bcf join BONDECOMMANDE_CLIENT bc on bc.id=bcf.IDBC where bc.ETAT>=11 group by PRODUIT, bc.IDPROFORMA
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENTBCETAT" ("ID", "IDSOUSECRITURE", "IDRELEVERDETAIL", "VALEURSOUSECRITURE", "VALEURRELEVERDETAIL", "DATY", "ETAT", "IDMERE") AS 
 select rp.id,rp.IDSOUSECRITURE,rp.IDRELEVERDETAIL,rp.VALEURSOUSECRITURE,rp.VALEURRELEVERDETAIL,rp.DATY,rpm.ETAT,rp.IDMERE from RapprochementBC rp join RAPPROCHEMENTBCMERE rpm on rp.IDMERE=rpm.ID
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RAPPROCHEMENT_FFOURNISSEURGRP" ("NUMBL", "TOTALLIVRER", "TOTALFACTURER") AS 
 SELECT bc.NUMBL, sum (bc.quantite ) AS totallivrer , sum (bc.qtefacturer ) AS totalFacturer FROM RAPPROCHEMENT_FFOURNISSEUR bc GROUP BY bc.NUMBL 

;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RELEVERDETAILCPL" ("ID", "IDMERE", "DATY", "DATYVALEUR", "DESIGNATION", "DEBIT", "CREDIT", "IDCAISSE", "COMPTE") AS 
 select rd."ID",rd."IDMERE",rd."DATY",rd."DATYVALEUR",rd."DESIGNATION",rd."DEBIT",rd."CREDIT" , r.IDCAISSE, cai.COMPTE from ReleverDetail rd join RELEVER r on rd.IDMERE = r.id left join CAISSE cai on cai.id=r.IDCAISSE

;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."RELEVERDETAILORDER" ("ID", "IDMERE", "DATY", "DATYVALEUR", "DESIGNATION", "DEBIT", "CREDIT", "SOLDE") AS 
 select "ID","IDMERE","DATY","DATYVALEUR","DESIGNATION","DEBIT","CREDIT","SOLDE" from ReleverDetail ORDER BY TO_NUMBER(REGEXP_REPLACE(id, '[^0-9]', '')) ASC

;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REMISEFILLEMERE" ("ID", "REMISE", "IDCATEGORIECLIENT", "IDPRODUIT", "CATEGORIEPRODUIT", "IDPOINT", "IDREMISE", "NOM", "DATY", "DATEDEBUT", "DATEFIN", "ETAT") AS 
 select rf."ID",rf."REMISE",rf."IDCATEGORIECLIENT",rf."IDPRODUIT",rf."CATEGORIEPRODUIT",rf."IDPOINT",rf."IDREMISE",r.nom,r.daty,r.dateDebut,r.dateFin,r.etat from remiseFille rf left join remise r on r.id=rf.idremise
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."REMISEFILLEMEREVISE" ("ID", "REMISE", "IDCATEGORIECLIENT", "IDPRODUIT", "CATEGORIEPRODUIT", "IDPOINT", "IDREMISE", "NOM", "DATY", "DATEDEBUT", "DATEFIN", "ETAT") AS 
 select rf."ID",rf."REMISE",rf."IDCATEGORIECLIENT",rf."IDPRODUIT",rf."CATEGORIEPRODUIT",rf."IDPOINT",rf."IDREMISE",r.nom,r.daty,r.dateDebut,r.dateFin,r.etat from remiseFille rf left join remise r on r.id=rf.idremise where r.etat>=11
;

  CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."SALAIREBASEMOIS" ("IDPERSONNEL", "MOIS", "ANNEE", "SALAIREBASE") AS 
  SELECT IDPERSONNEL,mois,annee,round(sum(gain),0) AS salairebase FROM paie_edition WHERE IDELEMENTPAIE IN (
    SELECT id FROM PAIE_RUBRIQUE pr WHERE TYPERUBRIQUE='G' AND IMPOSABLE = 'I'
) GROUP BY IDPERSONNEL,mois,annee
 ;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STATFILLE" ("ID", "LIBELLE", "QTE", "MONTANT", "DATY", "IDCLIENT", "IDPROVINCE", "FAMILLE", "IDFAMILLE", "REMISE") AS 
 select IDPRODUIT as id, LIBELLE, sum(qte) as qte, sum(montant) as montant, DATY, IDCLIENT, IDPROVINCE, famille, IDFAMILLE, sum(remise) as remise from balance_client group by IDPRODUIT, LIBELLE, daty, IDCLIENT, IDPROVINCE, famille, IDFAMILLE
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."STATMERE" ("ID", "FAMILLE", "QTE", "MONTANT", "DATY", "IDCLIENT", "IDPROVINCE") AS 
 select IDFAMILLE as id, famille, sum(qte) as qte, sum(montant) as montant, DATY, IDCLIENT, IDPROVINCE as idprovince  from balance_client group by IDFAMILLE, famille, daty, IDCLIENT,IDPROVINCE
;

 CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."ST_INGREDIENTSAUTOACHAT_CPL" ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEUSD", "PUVENTEEURO", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "COMPTE", "TAUX") AS 
