;

  CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TARIF_INGREDIENTS_MAX_DATE_MN" ("IDINGREDIENT", "UNITE", "IDTYPECLIENT", "DATY", "IDMAGASIN") AS 
  select IDINGREDIENT, UNITE, IDTYPECLIENT, max(DATY) as daty, IDMAGASIN
from (select * from TARIF_INGREDIENTS where idmagasin is null)
group by IDINGREDIENT, UNITE, IDTYPECLIENT, IDMAGASIN
 ;

  CREATE OR REPLACE FORCE VIEW "ARBIOCHEMSTANDARD"."TARIF_INGREDIENTS_MAX_DATE_MNN" ("IDINGREDIENT", "UNITE", "IDTYPECLIENT", "DATY", "IDMAGASIN") AS 
  select IDINGREDIENT, UNITE, IDTYPECLIENT, max(DATY) as daty, IDMAGASIN
from (select * from TARIF_INGREDIENTS where idmagasin is not null)
group by IDINGREDIENT, UNITE, IDTYPECLIENT, IDMAGASIN
 ;

